uniform vec4 inner;
uniform vec4 outer;
uniform vec3 paintX;
uniform vec3 paintY;
uniform vec2 extent;
uniform float radius;
uniform float feather;
uniform float strokeMultiplier;
uniform float fringe;
varying vec2 position;
varying vec2 coverage;
void main() {
    float mask = 1.0;
    if (fringe > 0.5)
        mask = clamp((1.0 - abs(coverage.x * 2.0 - 1.0)) * strokeMultiplier, 0.0, 1.0) * min(1.0, coverage.y);
    float amount = 0.0;
    if (feather != 0.0) {
        vec2 p = vec2(dot(paintX, vec3(position, 1.0)), dot(paintY, vec3(position, 1.0)));
        vec2 d = abs(p) - extent + vec2(radius);
        float distance = min(max(d.x, d.y), 0.0) + length(max(d, 0.0)) - radius;
        amount = clamp((distance + feather * 0.5) / feather, 0.0, 1.0);
    }
    vec4 color = mix(inner, outer, amount);
    gl_FragColor = vec4(color.rgb, color.a * mask);
}

